var peakIndexInMountainArray = function(arr) {
    let lo = 0;
    let hi = arr.length - 1;

    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);

        if (arr[mid] < arr[mid + 1]) {
            // Still ascending: peak is to the right
            lo = mid + 1;
        } else {
            // Descending or at peak: peak is at mid or to the left
            hi = mid;
        }
    }

    // lo === hi is the peak index
    return lo;
};
